package cl.acis.catalogos.service;
import cl.acis.catalogos.dto.*; import cl.acis.catalogos.exception.*; import cl.acis.catalogos.model.*; import cl.acis.catalogos.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; import java.util.*;
@Service public class FotoService {final FotoRepository repo;final Path dir;public FotoService(FotoRepository r,@Value("${acis.uploads-dir:uploads}")String d){repo=r;dir=Paths.get(d).toAbsolutePath().normalize();try{Files.createDirectories(dir);}catch(IOException e){throw new IllegalStateException("No se pudo crear uploads",e);}}
 public FotoResponse subir(MultipartFile archivo,Long orden,TipoFoto tipo,Long actor,Double lat,Double lon){if(archivo.isEmpty())throw new ReglaNegocioException("El archivo está vacío");String nombre=Objects.requireNonNullElse(archivo.getOriginalFilename(),"").toLowerCase();if(!(nombre.endsWith(".jpg")||nombre.endsWith(".png")))throw new ReglaNegocioException("Solo se permiten archivos JPG y PNG");if(archivo.getSize()>5*1024*1024)throw new ReglaNegocioException("La imagen supera el límite de 5 MB");String guardado=UUID.randomUUID()+ (nombre.endsWith(".png")?".png":".jpg");Path destino=dir.resolve(guardado).normalize();try{if(!destino.getParent().equals(dir))throw new ReglaNegocioException("Ruta de archivo no válida");archivo.transferTo(destino);}catch(IOException e){throw new ReglaNegocioException("No se pudo guardar la imagen");}FotoEvidencia f=new FotoEvidencia();f.setOrdenId(orden);f.setNombreArchivo(archivo.getOriginalFilename());f.setRutaArchivo(destinoRelativo(guardado));f.setTipo(tipo);f.setSubidaPorId(actor);f.setLatitud(lat);f.setLongitud(lon);return dto(repo.save(f));}
 public List<FotoResponse> listar(Long orden){return repo.findByOrdenId(orden).stream().map(this::dto).toList();}public Resource archivo(Long id){FotoEvidencia f=get(id);Resource r=new FileSystemResource(dir.resolve(Paths.get(f.getRutaArchivo())).normalize());if(!r.exists())throw new RecursoNoEncontradoException("Archivo no encontrado");return r;}public String nombre(Long id){return get(id).getNombreArchivo();}public void borrar(Long id){FotoEvidencia f=get(id);try{Files.deleteIfExists(dir.resolve(Paths.get(f.getRutaArchivo())).normalize());}catch(IOException e){throw new ReglaNegocioException("No se pudo borrar el archivo");}repo.delete(f);}private String destinoRelativo(String n){return n;}private FotoEvidencia get(Long id){return repo.findById(id).orElseThrow(()->new RecursoNoEncontradoException("Foto no encontrada"));}private FotoResponse dto(FotoEvidencia f){return new FotoResponse(f.getId(),f.getOrdenId(),f.getNombreArchivo(),f.getTipo(),f.getLatitud(),f.getLongitud(),f.getSubidaPorId(),f.getCreadaEn());}
}
